/* Client-site screenshots for portfolio cards + bilingual blog guide.
   Deferred data-URI map: keeps the main HTML lean; images fade in when applied. */
(function () {
  var SHOTS = {
    ruspa: "data:image/webp;base64,",
    alrayyan: "data:image/webp;base64,",
    dribrar: "data:image/webp;base64,",
    luxuryspa: "data:image/webp;base64,"
  };
  function apply() {
    document.querySelectorAll('img[data-shot]').forEach(function (img) {
      var k = img.getAttribute('data-shot');
      var uri = SHOTS[k];
      if (!uri) return;
      if (img.getAttribute('src') !== uri) {
        img.onload = function () { img.style.opacity = '1'; };
        img.setAttribute('src', uri);
        if (img.complete && img.naturalWidth > 0) img.style.opacity = '1';
      } else if (img.complete && img.naturalWidth > 0) {
        img.style.opacity = '1';
      }
    });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', apply); else apply();
  window.addEventListener('load', apply);
  if ('MutationObserver' in window) {
    var mo = new MutationObserver(apply);
    ['portfolio-cards-grid', 'blog-cards-grid', 'blog-grid'].forEach(function (id) {
      var el = document.getElementById(id);
      if (el) mo.observe(el, { childList: true, subtree: true });
    });
  }
})();
